-- ============================================================
--  الخطة التشغيلية لإدارة عمليات الأداء — 2026م
--  ------------------------------------------------------------
--  خمس محافظ، لكل مديرٍ محفظة، وداخل كل محفظة ثلاثة أنواع من
--  المساهمات: مؤشرات · مبادرات · مكاسب سريعة. ولكل مساهمة
--  **راعٍ** و**مسؤول** — والراعي قد لا يكون صاحب المحفظة.
--
--  القسم `opplan` يمرّ بسياسات `perf_items` القائمة: القراءة لمن
--  يملك صلاحية باسم القسم، والكتابة له مع `sections:edit`.
--
--  idempotent: الصفوف تُحدَّث بمعرّفاتها ولا تتكرّر.
-- ============================================================

-- الصلاحية: العرض لكل حساب نشط — خطة الإدارة يعرفها الجميع
update public.perf_users
   set scopes = (select array(select distinct unnest(coalesce(scopes,'{}') || array['opplan'])))
 where active and not (coalesce(scopes,'{}') @> array['opplan']);

on conflict (section, id) do update
  set ord = excluded.ord,
      data = public.perf_items.data || excluded.data;

select count(*) filter (where data->>'kind' = 'kpi')  as "مؤشرات",
       count(*) filter (where data->>'kind' = 'init') as "مبادرات",
       count(*) filter (where data->>'kind' = 'win')  as "مكاسب"
  from public.perf_items where section = 'opplan';
